#include <iostream>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, k;
    cin >> n >> k;

    if (k == 1) {
        cout << 1 << '\n';
        return 0;
    }

    ll left = 1, right = n, answer = n;

    while (left <= right) {
        ll mid = left + (right - left) / 2;
        ll sum = 0;

        for (ll term = mid; term > 0; term /= k) {
            sum += term;
            if (sum >= n) break;
        }

        if (sum >= n) {
            answer = mid;
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }

    cout << answer << '\n';
    return 0;
}

